import json

with open('json/posts.json', 'r') as f:
    data = json.load(f)

records = data.get('records', []) or []

# Search for posts containing "Game" in title
game_posts = []
for record in records:
    if not isinstance(record, dict):
        continue
    title = record.get('Title')
    if title and 'Game' in str(title):
        game_posts.append(record)

print(f"Posts with 'Game' in title: {len(game_posts)}")
for p in game_posts[:10]:
    print(f"  Title='{p.get('Title')}', ViewCount={p.get('ViewCount')}, OwnerUserId={p.get('OwnerUserId')}")

# Also search for "Datasets"
dataset_posts = []
for record in records:
    if not isinstance(record, dict):
        continue
    title = record.get('Title')
    if title and 'Dataset' in str(title):
        dataset_posts.append(record)

print(f"\nPosts with 'Dataset' in title: {len(dataset_posts)}")
for p in dataset_posts[:10]:
    print(f"  Title='{p.get('Title')}', ViewCount={p.get('ViewCount')}, OwnerUserId={p.get('OwnerUserId')}")
